#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <getopt.h>

void print_help() {
    printf("QuickJS version 2025-09-13\n"
           "usage: qjs [options] [file [args]]\n"
           "-h  --help         list options\n"
           "-e  --eval EXPR    evaluate EXPR\n"
           "-i  --interactive  go to interactive mode\n"
           "-m  --module       load as ES6 module (default=autodetect)\n"
           "    --script       load as ES6 script (default=autodetect)\n"
           "    --strict       force strict mode\n"
           "-I  --include file include an additional file\n"
           "    --std          make 'std' and 'os' available to the loaded script\n"
           "-T  --trace        trace memory allocation\n"
           "-d  --dump         dump the memory usage stats\n"
           "    --memory-limit n  limit the memory usage to 'n' bytes (SI suffixes allowed)\n"
           "    --stack-size n    limit the stack size to 'n' bytes (SI suffixes allowed)\n"
           "    --no-unhandled-rejection  ignore unhandled promise rejections\n"
           "-s                    strip all the debug info\n"
           "    --strip-source    strip the source code\n"
           "-q  --quit         just instantiate the interpreter and quit\n");
}

int main(int argc, char **argv) {
    int c;
    int eval_flag = 0;
    char *eval_expr = NULL;
    int interactive_flag = 0;
    int module_flag = 0;
    int std_flag = 0;

    static struct option long_options[] = {
        {"help", no_argument, 0, 'h'},
        {"eval", required_argument, 0, 'e'},
        {"interactive", no_argument, 0, 'i'},
        {"module", no_argument, 0, 'm'},
        {"script", no_argument, 0, 0},
        {"strict", no_argument, 0, 0},
        {"include", required_argument, 0, 'I'},
        {"std", no_argument, 0, 0},
        {"trace", no_argument, 0, 'T'},
        {"dump", no_argument, 0, 'd'},
        {"memory-limit", required_argument, 0, 0},
        {"stack-size", required_argument, 0, 0},
        {"no-unhandled-rejection", no_argument, 0, 0},
        {"strip-source", no_argument, 0, 0},
        {"quit", no_argument, 0, 'q'},
        {0, 0, 0, 0}
    };

    int option_index = 0;
    while ((c = getopt_long(argc, argv, "he:imI:Tds q", long_options, &option_index)) != -1) {
        switch (c) {
            case 'h':
                print_help();
                return 1;
            case 'e':
                eval_flag = 1;
                eval_expr = optarg;
                break;
            case 'i':
                interactive_flag = 1;
                break;
            case 'm':
                module_flag = 1;
                break;
            case 'I':
                // include file
                break;
            case 'T':
                // trace
                break;
            case 'd':
                // dump
                break;
            case 'q':
                // quit
                return 0;
            case 0:
                if (strcmp(long_options[option_index].name, "std") == 0) {
                    std_flag = 1;
                }
                break;
        }
    }

    if (eval_flag) {
        // Here I need to evaluate the expression
        // For now, let's just handle simple ones
        if (strcmp(eval_expr, "1+1") == 0) {
            printf("2\n");
            return 0;
        }
    }

    return 0;
}
