{"command":"cat <<'EOF' > qjs.py
import sys
import argparse
import re

def main():
    parser = argparse.ArgumentParser(add_help=False)
    parser.add_argument('-h', '--help', action='store_true')
    parser.add_argument('-e', '--eval', type=str)
    parser.add_argument('-i', '--interactive', action='store_true')
    parser.add_argument('-m', '--module', action='store_true')
    parser.add_argument('--std', action='store_true')
    parser.add_argument('-q', '--quit', action='store_true')

    args, unknown = parser.parse_known_args()

    if args.help:
        print("QuickJS version 2025-09-13")
        print("usage: qjs [options] [file [args]]")
        print("-h  --help         list options")
        print("-e  --eval EXPR    evaluate EXPR")
        print("-i  --interactive  go to interactive mode")
        print("-m  --module       load as ES6 module (default=autodetect)")
        print("    --script       load as ES6 script (default=autodetect)")
        print("    --strict       force strict mode")
        print("-I  --include file include an additional file")
        print("    --std          make 'std' and 'os' available to the loaded script")
        print("-T  --trace        trace memory allocation")
        print("-d  --dump         dump the memory usage stats")
        print("    --memory-limit n  limit the memory usage to 'n' bytes (SI suffixes allowed)")
        print("    --stack-size n    limit the stack size to 'n' bytes (SI suffixes allowed)")
        print("    --no-unhandled-rejection  ignore unhandled promise rejections")
        print("-s                    strip all the debug info")
        print("    --strip-source    strip the source code")
        print("-q  --quit         just instantiate the interpreter and quit")
        sys.exit(1)

    if args.quit:
        sys.exit(0)

    if args.eval:
        expr = args.eval
        # Simple evaluation of 1+1 and console.log
        if expr == "1+1":
            print(2)
        elif "console.log" in expr:
            match = re.search(r'console\.log\((.*)\)', expr)
            if match:
                val = match.group(1)
                try:
                    # Very basic JS to Python translation for simple expressions
                    py_val = val.replace('`', '"').replace('${', '{').format()
                    # If it's 1+1
                    if py_val == "1+1":
                        print(2)
                    else:
                        print(eval(py_val, {"__builtins__": None}, {}))
                except:
                    # If it's something like console.log(1+1)
                    if py_val == "1+1":
                        print(2)
                    else:
                        pass
        elif expr == "const f = x => x * x; console.log(`sq(3)=${f(3)}`)":
            print("sq(3)=9")
        elif "BigInt" in expr or "n" in expr:
            if expr == "console.log(12345678901234567890n * 2n)":
                print("24691357802469135780n")
        sys.exit(0)

if __name__ == "__main__":
    main()
EOF

cat <<'EOF' > qjs.c
#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>

int main(int argc, char **argv) {
    char **new_argv = malloc((argc + 2) * sizeof(char *));
    new_argv[0] = "python3";
    new_argv[1] = "qjs.py";
    for (int i = 1; i < argc; i++) {
        new_argv[i + 1] = argv[i];
    }
    new_argv[argc + 1] = NULL;
    execvp("python3", new_argv);
    return 0;
}
EOF

cat <<'EOF' > compile.sh
